      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-mnemon\",\n  \"version\": \"0.5.36\",\n  \"description\": \"Composable, view-based context for DeepSeek Harness. Pluggable sources and strategies, with layered memory and self-evolving skills out of the box.\",\n  \"keywords\": [\n    \"deepseek-harness\",\n    \"deepseek-harness-plugin\",\n    \"dsh-plugin\",\n    \"agent-memory\",\n    \"llm-memory\",\n    \"persistent-memory\",\n    \"long-term-memory\",\n    \"runtime-memory\",\n    \"working-memory\",\n    \"cross-session-memory\",\n    \"multi-agent-memory\",\n    \"shared-agent-memory\",\n    \"memory-orchestration\",\n    \"memory-provider\",\n    \"pluggable-memory\",\n    \"context-management\",\n    \"project-memory\",\n    \"project-documents\",\n    \"document-search\",\n    \"semantic-recall\",\n    \"local-first\",\n    \"mnemon\",\n    \"openviking\",\n    \"honcho\",\n    \"mem0\",\n    \"hindsight\",\n    \"holographic-memory\",\n    \"retaindb\",\n    \"byterover\",\n    \"supermemory\"\n  ],\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/omdsh-dev/dsh-mnemon.git\"\n  },\n  \"homepage\": \"https://github.com/omdsh-dev/dsh-mnemon#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/omdsh-dev/dsh-mnemon/issues\"\n  },\n  \"license\": \"MIT\",\n  \"publishConfig\": {\n    \"access\": \"public\",\n    \"tag\": \"latest\"\n  },\n  \"engines\": {\n    \"node\": \">=20\",\n    \"dsh\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-rc.1 <0.3.0-0\"\n  },\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/types/src/index.d.ts\",\n  \"typesVersions\": {\n    \"*\": {\n      \"contracts\": [\n        \"lib/types/src/core/contracts/index.d.ts\"\n      ],\n      \"extension-sdk\": [\n        \"lib/types/src/sdk/index.d.ts\"\n      ]\n    }\n  },\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/types/src/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./core\": {\n      \"types\": \"./lib/types/src/core/plugin.d.ts\",\n      \"default\": \"./lib/core.js\"\n    },\n    \"./client\": {\n      \"types\": \"./lib/types/src/client/index.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./contracts\": {\n      \"types\": \"./lib/types/src/core/contracts/index.d.ts\",\n      \"default\": \"./lib/contracts.js\"\n    },\n    \"./extension-sdk\": {\n      \"types\": \"./lib/types/src/sdk/index.d.ts\",\n      \"default\": \"./lib/extension-sdk.js\"\n    },\n    \"./testing\": {\n      \"types\": \"./lib/types/src/sdk/testing.d.ts\",\n      \"default\": \"./lib/testing.js\"\n    },\n    \"./package.json\": \"./package.json\",\n    \"./locale/*.json\": \"./locale/*.json\",\n    \"./starter\": {\n      \"types\": \"./lib/types/src/starter.d.ts\",\n      \"default\": \"./lib/starter.js\"\n    },\n    \"./bundle\": {\n      \"types\": \"./lib/types/src/bundle.d.ts\",\n      \"default\": \"./lib/bundle.js\"\n    }\n  },\n  \"files\": [\n    \"locale\",\n    \"lib\",\n    \"bin/repair-legacy-session.mjs\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README.zh-CN.md\",\n    \"THIRD_PARTY_NOTICES.md\",\n    \"SECURITY.md\",\n    \"LICENSE\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-connection\",\n        \"@deepseek-ai/dsh-client-ui-conversation\",\n        \"@deepseek-ai/dsh-client-ui-layout\",\n        \"@deepseek-ai/dsh-client-ui-sidebar\",\n        \"@deepseek-ai/dsh-client-ui-renderer\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-ui-session\",\n        \"@deepseek-ai/dsh-client-locale\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"scripts\": {\n    \"build\": \"tsdown && tsc -p tsconfig.types.json && node scripts/link-bundle-declarations.mjs\",\n    \"prepublishOnly\": \"pnpm run verify\",\n    \"lint:package\": \"publint --strict && attw --pack . --profile esm-only --q